"""
Module for managing the qBraid environment registry.

The registry provides a central source of truth for all Python environments
tracked by qBraid, including qBraid-managed, temporary, and external environments.
"""

import json
import logging
import platform as platform_module
import secrets
import shutil
import string
import sys
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Generator, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, field_serializer, field_validator

from qbraid_core.system.executables import is_valid_python

from .exceptions import EnvironmentNotFoundError
from .paths import (
    extract_alias_from_path,
    find_python_in_env,
    get_default_envs_paths,
    is_temporary_location,
)
from .schema import EnvironmentConfig
from .validate import is_valid_slug

logger = logging.getLogger(__name__)


def generate_env_id() -> str:
    """Generate a random 4-digit alphanumeric environment ID.

    Returns:
        str: 4-character alphanumeric ID (e.g., "a1b2", "x9k3")
    """
    chars = string.ascii_lowercase + string.digits
    return "".join(secrets.choice(chars) for _ in range(4))


def get_current_platform() -> str:
    """Get current platform identifier.

    Returns:
        str: Platform identifier (e.g., "linux-x86_64", "darwin-arm64", "win32-amd64")
    """
    system = platform_module.system().lower()
    machine = platform_module.machine().lower()

    # Normalize system names
    if system == "windows":
        system = "win32"

    # Normalize machine names
    if machine in ("x86_64", "amd64"):
        machine = "x86_64"
    elif machine in ("arm64", "aarch64"):
        machine = "arm64"

    return f"{system}-{machine}"


def verify_python_executable(python_path: Path) -> tuple[bool, str]:
    """Verify that a Python executable is valid and working.

    Checks:
    1. Path exists (or is a valid symlink)
    2. Symlink target exists (if symlink)
    3. Is actually executable
    4. Can run python --version

    Args:
        python_path: Path to Python executable

    Returns:
        tuple[bool, str]: (is_valid, message)
    """
    import subprocess  # pylint: disable=import-outside-toplevel

    python_path = Path(python_path)

    if not python_path.exists() and not python_path.is_symlink():
        return False, f"Python executable not found: {python_path}"

    # Check if symlink and if target exists
    if python_path.is_symlink():
        try:
            target = python_path.resolve()
            if not target.exists():
                return False, f"Python symlink broken: {python_path} -> {target}"
        except OSError as err:
            return False, f"Cannot resolve symlink: {python_path} - {err}"

    # Check if executable
    if not is_valid_python(python_path):
        return False, f"Not a valid Python executable: {python_path}"

    # Try to run python --version
    try:
        result = subprocess.run(
            [str(python_path), "--version"],
            capture_output=True,
            timeout=10,
            check=False,
        )
        if result.returncode != 0:
            stderr = result.stderr.decode("utf-8", errors="replace")
            return False, f"Python --version failed: {stderr}"
    except subprocess.TimeoutExpired:
        return False, f"Python --version timed out: {python_path}"
    except (OSError, subprocess.SubprocessError) as err:
        return False, f"Failed to run Python: {err}"

    return True, "Python executable is valid"


EnvironmentType = Literal["qbraid-managed", "external", "temporary"]


class EnvironmentEntry(BaseModel):
    """Single environment entry in the registry.

    Attributes:
        env_id: Unique identifier on user's computer (4-digit alphanumeric, e.g., "a1b2")
        slug: Unique identifier on qBraid cloud database (optional, for cloud environments)
        path: Filesystem path to the environment
        type: Type of environment (qbraid-managed, external, temporary)
        name: Environment name (required, from EnvironmentConfig)
        description: Environment description
        tags: List of tags
        logo_url: Remote URLs to logo files {"light": "https://...", "dark": "https://..."}
        python_version: Python version (e.g., "3.11.0")
        python_executable: Full path to Python binary (detected or from kernel.json)
        platform: Platform info (e.g., "linux-x86_64", "darwin-arm64")
        kernel_name: Display name for Jupyter kernel
        shell_prompt: Shell prompt string
        python_packages: Dict of package names and version specifiers
        visibility: Visibility setting (default: "private")
        access_key: Share code for private environments (e.g., "RONWBYZU")
        read_access_users: List of emails of users with read access
        groups: List of environment group slugs this environment belongs to
        installed_at: ISO timestamp when environment was installed (qbraid-managed)
        registered_at: ISO timestamp when environment was registered (external)
        is_temporary: Whether this is a temporary environment
        metadata: Additional metadata about the environment (e.g., install status)
    """

    model_config = ConfigDict(extra="ignore")

    env_id: str  # Unique identifier on user's computer (4-digit alphanumeric)
    slug: Optional[str] = None  # Cloud identifier (for downloaded/published environments)
    owner: Optional[dict[str, str]] = (
        None  # Owner info {"username": "...", "email": "..."} from API
    )
    path: Path
    type: EnvironmentType
    name: str  # Required field from EnvironmentConfig
    description: Optional[str] = None
    tags: Optional[list[str]] = None
    logo_url: Optional[dict[str, str]] = None  # {"light": "https://...", "dark": "https://..."}
    python_version: Optional[str] = None
    python_executable: Optional[Path] = None  # Full path to Python binary
    platform: Optional[str] = None  # Platform info (e.g., "linux-x86_64", "darwin-arm64")
    kernel_name: Optional[str] = None
    shell_prompt: Optional[str] = None
    python_packages: Optional[dict[str, str]] = None
    visibility: str = "private"
    access_key: Optional[str] = None  # Share code for private environments
    read_access_users: Optional[list[str]] = None  # Emails of users with read access
    groups: Optional[list[str]] = None  # Environment group slugs
    installed_at: Optional[str] = None
    registered_at: Optional[str] = None
    is_temporary: bool = False
    metadata: dict = Field(default_factory=dict)

    @field_serializer("path")
    def serialize_path(self, path: Path) -> str:
        """Serialize Path to string."""
        return str(path)

    @field_validator("path", mode="before")
    @classmethod
    def validate_path(cls, v):
        """Convert string to Path if needed."""
        if isinstance(v, str):
            return Path(v)
        return v

    @field_validator("python_executable", mode="before")
    @classmethod
    def validate_python_executable(cls, v):
        """Convert string to Path if needed."""
        if isinstance(v, str):
            return Path(v)
        return v

    @field_serializer("python_executable")
    def serialize_python_executable(self, python_executable: Optional[Path]) -> Optional[str]:
        """Serialize Path to string."""
        return str(python_executable) if python_executable else None

    def get_base_alias(self) -> str:
        """Get base alias from name (name is required field).

        Returns:
            str: Environment name (used as base alias)
        """
        return self.name


# pylint: disable-next=too-few-public-methods
class EnvironmentRegistry(BaseModel):
    """Central registry for all qBraid-tracked environments.

    Attributes:
        version: Registry schema version
        environments: Dictionary mapping env_id to environment entry
    """

    version: str = "3.0"  # Updated to use env_id as key, slug stored in entry
    environments: dict[str, EnvironmentEntry] = Field(default_factory=dict)


class EnvironmentRegistryManager:
    """Manages the environment registry file.

    The registry is stored at ~/.qbraid/environments.json and tracks all
    Python environments that qBraid knows about, regardless of location or type.
    """

    def __init__(self, registry_path: Optional[Path] = None):
        """Initialize the registry manager.

        Args:
            registry_path: Path to registry file. Defaults to ~/.qbraid/environments.json
        """
        self.registry_path = registry_path or self._get_default_registry_path()
        self.registry = self.load_registry()

    @staticmethod
    def _get_default_registry_path() -> Path:
        """Get the default registry file path."""
        return Path.home() / ".qbraid" / "environments.json"

    @contextmanager
    def _registry_lock(self) -> Generator[None, None, None]:
        """Context manager for exclusive file locking on the registry.

        Uses fcntl.flock on Unix or msvcrt.locking on Windows for
        cross-process/cross-thread file locking. This ensures atomic
        read-modify-write operations on the registry file.
        """
        lock_path = self.registry_path.with_suffix(".json.lock")
        lock_path.parent.mkdir(parents=True, exist_ok=True)

        with open(lock_path, "w", encoding="utf-8") as lock_file:
            try:
                if sys.platform == "win32":
                    import msvcrt  # pylint: disable=import-outside-toplevel

                    msvcrt.locking(lock_file.fileno(), msvcrt.LK_LOCK, 1)
                else:
                    import fcntl  # pylint: disable=import-outside-toplevel

                    fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
                yield
            finally:
                if sys.platform == "win32":
                    import msvcrt  # pylint: disable=import-outside-toplevel

                    try:
                        msvcrt.locking(lock_file.fileno(), msvcrt.LK_UNLCK, 1)
                    except OSError:
                        pass
                else:
                    import fcntl  # pylint: disable=import-outside-toplevel

                    fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)

    @staticmethod
    def _migrate_registry_data(data: dict) -> dict:
        """Migrate old registry formats to current schema.

        Handles schema changes like:
        - Adding required 'name' field (defaults to 'alias' or path-based name)
        - Converting old field names to new ones

        Args:
            data: Raw registry data from JSON

        Returns:
            dict: Migrated registry data compatible with current schema
        """
        if "environments" not in data:
            return data

        environments = data.get("environments")
        if not isinstance(environments, dict):
            # Invalid format - reset to empty dict
            logger.warning("Registry 'environments' field is not a dict, resetting to empty")
            data["environments"] = {}
            return data

        migrated = False
        for env_id, entry in environments.items():
            if not isinstance(entry, dict):
                continue

            # Migration: 'name' field is now required
            # Fall back to 'alias' (old field name) or path-based name
            if "name" not in entry or entry.get("name") is None:
                if "alias" in entry and entry["alias"]:
                    entry["name"] = entry["alias"]
                    migrated = True
                elif "path" in entry:
                    # Extract name from path (last component or slug)
                    path_str = entry["path"]
                    entry["name"] = Path(path_str).name
                    migrated = True
                else:
                    # Last resort: use env_id as name
                    entry["name"] = env_id
                    migrated = True

            # Remove deprecated 'alias' field if present (now redundant with 'name')
            if "alias" in entry:
                del entry["alias"]
                migrated = True

        if migrated:
            logger.info("Migrated registry data to current schema")

        return data

    def load_registry(self) -> EnvironmentRegistry:
        """Load registry from file, create if doesn't exist.

        Automatically migrates old registry formats to current schema.

        Returns:
            EnvironmentRegistry: Loaded registry or new empty registry
        """
        if self.registry_path.exists():
            try:
                with open(self.registry_path, "r", encoding="utf-8") as f:
                    data = json.load(f)

                # Migrate old formats before validation
                data = self._migrate_registry_data(data)

                registry = EnvironmentRegistry(**data)

                # Log if we loaded an empty registry from a non-empty file
                if not registry.environments and data.get("environments"):
                    logger.warning(
                        "Registry loaded but environments dict is empty after migration. "
                        "Original data had %d entries.",
                        len(data.get("environments", {})),
                    )

                return registry
            except json.JSONDecodeError as err:
                logger.warning("Registry JSON is corrupted: %s", err)
                self._backup_registry("corrupted")
            except ValueError as err:
                # Pydantic validation failed even after migration
                logger.warning("Registry validation failed after migration: %s", err)
                self._backup_registry("invalid")
            except Exception as err:
                # Catch any other unexpected errors (e.g., from migration)
                logger.warning("Unexpected error loading registry: %s: %s", type(err).__name__, err)
                self._backup_registry("error")

        return EnvironmentRegistry()

    def _backup_registry(self, reason: str) -> None:
        """Backup the registry file before resetting.

        Args:
            reason: Short description of why backup is being made
        """
        backup_path = self.registry_path.with_suffix(".json.backup")
        if self.registry_path.exists():
            self.registry_path.rename(backup_path)
            logger.info("Backed up %s registry to %s", reason, backup_path)

    def save_registry(self, _bypass_safeguard: bool = False) -> None:
        """Save registry to file.

        Includes a safeguard: refuses to save an empty registry when
        environment directories exist on disk, and logs the stack trace.
        The safeguard only applies when using the default registry path.

        Args:
            _bypass_safeguard: If True, skip the empty registry safeguard.
                Used by intentional operations like unregister_environment.
                Do not use this flag unless you know what you're doing.
        """
        self.registry_path.parent.mkdir(parents=True, exist_ok=True)

        # Safeguard: BLOCK saving empty registry when env dirs exist
        # Only applies when using the default registry path (skip for tests/custom paths)
        # Skip safeguard for intentional operations (unregister, cleanup)
        default_registry_path = self._get_default_registry_path()
        if (
            not _bypass_safeguard
            and not self.registry.environments
            and self.registry_path == default_registry_path
        ):
            env_dirs = list(get_default_envs_paths())
            for env_path in env_dirs:
                if env_path.exists():
                    subdirs = [d for d in env_path.iterdir() if d.is_dir()]
                    # Filter out hidden directories and check for actual envs
                    env_subdirs = [d for d in subdirs if not d.name.startswith(".")]
                    if env_subdirs:
                        import traceback

                        stack_trace = "".join(traceback.format_stack())
                        timestamp = datetime.now().isoformat()

                        # Log to file for debugging
                        debug_file = self.registry_path.parent / "registry_debug.log"
                        with open(debug_file, "a", encoding="utf-8") as f:
                            f.write(f"\n{'='*60}\n")
                            f.write(f"BLOCKED EMPTY REGISTRY SAVE at {timestamp}\n")
                            f.write(f"Env directories exist: {[d.name for d in env_subdirs]}\n")
                            f.write(f"Stack trace:\n{stack_trace}\n")

                        logger.warning(
                            "BLOCKED: Refusing to save empty registry. "
                            "Env directories exist: %s. See ~/.qbraid/registry_debug.log",
                            [d.name for d in env_subdirs[:5]],
                        )
                        # DO NOT SAVE - return early to protect the registry
                        return

        # Serialize with custom handling for Path objects
        registry_dict = self.registry.model_dump(mode="json")

        with open(self.registry_path, "w", encoding="utf-8") as f:
            json.dump(registry_dict, f, indent=2)

        logger.debug("Registry saved to %s", self.registry_path)

    def register_environment(
        self,
        path: Path,
        env_type: EnvironmentType,
        env_id: Optional[str] = None,
        slug: Optional[str] = None,
        owner: Optional[dict[str, str]] = None,
        config: Optional[EnvironmentConfig] = None,
        name: Optional[str] = None,
        description: Optional[str] = None,
        tags: Optional[list[str]] = None,
        logo_url: Optional[dict[str, str]] = None,
        python_version: Optional[str] = None,
        python_executable: Optional[Path] = None,
        platform: Optional[str] = None,
        kernel_name: Optional[str] = None,
        shell_prompt: Optional[str] = None,
        python_packages: Optional[dict[str, str]] = None,
        visibility: str = "private",
        access_key: Optional[str] = None,
        read_access_users: Optional[list[str]] = None,
        groups: Optional[list[str]] = None,
        is_temporary: bool = False,
        metadata: Optional[dict] = None,
    ) -> str:
        """Register a new environment.

        Args:
            path: Filesystem path to the environment
            env_type: Type of environment
            env_id: Environment ID (4-digit alphanumeric). If None, generates unique ID.
            slug: Cloud identifier (optional, for downloaded/published environments)
            owner: Owner info dict {"username": "...", "email": "..."} from API
                   (for downloaded envs) or current user info (for local envs).
            config: EnvironmentConfig object (if provided, other fields are ignored)
            name: Environment name (required if config not provided)
            description: Environment description
            tags: List of tags
            logo_url: Remote URLs to logo files {"light": "https://...", "dark": "https://..."}
            python_version: Python version
            python_executable: Full path to Python binary. If None, auto-detected.
            platform: Platform identifier (e.g., "linux-x86_64"). If None, uses current platform.
            kernel_name: Display name for Jupyter kernel
            shell_prompt: Shell prompt string
            python_packages: Dict of package names and version specifiers
            visibility: Visibility setting (default: "private")
            access_key: Share code for private environments (e.g., "RONWBYZU")
            read_access_users: List of emails of users with read access
            groups: List of environment group slugs
            is_temporary: Whether this is a temporary environment
            metadata: Additional metadata to store (e.g., install status)

        Returns:
            str: The env_id used for registration

        Raises:
            ValueError: If name conflicts with existing environment and env_id not provided
        """
        now = datetime.now(timezone.utc).isoformat()

        # Use config if provided, otherwise use individual fields
        # Direct parameters override config values if both provided
        if config:
            env_name = config.name
            env_description = config.description
            env_tags = config.tags
            env_python_version = config.python_version
            env_platform_from_config = getattr(config, "platform", None)
            env_kernel_name = config.kernel_name
            env_shell_prompt = config.shell_prompt
            env_python_packages = python_packages if python_packages else config.python_packages
            env_visibility = config.visibility
        else:
            if name is None:
                raise ValueError("Either config or name must be provided")
            env_name = name
            env_description = description
            env_tags = tags
            env_python_version = python_version
            env_platform_from_config = None
            env_kernel_name = kernel_name
            env_shell_prompt = shell_prompt
            env_python_packages = python_packages
            env_visibility = visibility

        # Track if env_id was explicitly provided by caller
        env_id_was_provided = env_id is not None

        # Generate unique env_id if not provided
        if env_id is None:
            env_id = self._generate_unique_env_id()

        # Auto-detect python_executable if not provided
        env_python_executable = python_executable
        if env_python_executable is None and path.exists():
            detected = find_python_in_env(path, validate=False)
            if detected:
                env_python_executable = Path(detected)

        # Auto-detect platform if not provided
        # Priority: direct parameter > config value > auto-detect
        env_platform = platform or env_platform_from_config or get_current_platform()

        # Normalize owner: API may return a string (user ID) instead of dict
        if isinstance(owner, str):
            owner = None

        # Create entry
        entry = EnvironmentEntry(
            env_id=env_id,
            slug=slug,
            owner=owner,
            path=path,
            type=env_type,
            name=env_name,
            description=env_description,
            tags=env_tags,
            logo_url=logo_url,
            python_version=env_python_version,
            python_executable=env_python_executable,
            platform=env_platform,
            kernel_name=env_kernel_name,
            shell_prompt=env_shell_prompt,
            python_packages=env_python_packages,
            visibility=env_visibility,
            access_key=access_key,
            read_access_users=read_access_users,
            groups=groups,
            installed_at=now if env_type in ("qbraid-managed", "temporary") else None,
            registered_at=now if env_type == "external" else None,
            is_temporary=is_temporary,
            metadata=metadata or {},
        )

        # Use file locking for atomic read-modify-write
        # This prevents race conditions when multiple processes/threads register simultaneously
        with self._registry_lock():
            # Re-load registry to get fresh state (another thread may have modified it)
            self.registry = self.load_registry()

            # Handle env_id conflicts:
            # - If env_id was explicitly provided and exists: update (upsert behavior)
            # - If env_id was auto-generated and conflicts: generate a new one
            if env_id in self.registry.environments:
                if env_id_was_provided:
                    # Upsert: user explicitly provided this env_id, update existing entry
                    logger.debug("Updating existing environment entry: %s", env_id)
                else:
                    # Auto-generated env_id conflicts (rare), generate a new one
                    env_id = self._generate_unique_env_id()
                    entry.env_id = env_id

            self.registry.environments[env_id] = entry
            self.save_registry()

        # Write per-env manifest for recovery
        self.save_env_manifest(env_id)

        logger.info("Registered environment: %s (env_id: %s, slug: %s)", env_name, env_id, slug)
        return env_id

    def _generate_unique_env_id(self) -> str:
        """Generate a unique env_id that doesn't exist in registry.

        Returns:
            str: Unique 4-digit alphanumeric env_id
        """
        max_attempts = 100
        for _ in range(max_attempts):
            env_id = generate_env_id()
            if env_id not in self.registry.environments:
                return env_id
        raise RuntimeError("Failed to generate unique env_id after 100 attempts")

    def unregister_environment(self, env_id: str) -> None:
        """Remove environment from registry.

        Args:
            env_id: Environment ID to remove

        Raises:
            EnvironmentNotFoundError: If the environment is not found in the registry
        """
        with self._registry_lock():
            # Re-load to get fresh state
            self.registry = self.load_registry()

            if env_id not in self.registry.environments:
                raise EnvironmentNotFoundError(f"Environment '{env_id}' not found in registry")

            # Log warning if this will result in empty registry
            if len(self.registry.environments) == 1:
                logger.warning(
                    "Unregistering last environment '%s'. Registry will be empty after this.",
                    env_id,
                )

            del self.registry.environments[env_id]
            # Bypass safeguard for intentional unregister operations
            self.save_registry(_bypass_safeguard=True)

        logger.info("Unregistered environment: %s", env_id)

    def get_environment(self, env_id: str) -> EnvironmentEntry:
        """Get environment entry by env_id.

        Args:
            env_id: Environment ID

        Returns:
            EnvironmentEntry: Environment entry

        Raises:
            EnvironmentNotFoundError: If the environment is not found in the registry
        """
        entry = self.registry.environments.get(env_id)
        if entry is None:
            raise EnvironmentNotFoundError(f"Environment '{env_id}' not found in registry")
        return entry

    def list_environments(
        self,
        env_type: Optional[EnvironmentType] = None,
        include_temporary: bool = True,
    ) -> dict[str, EnvironmentEntry]:
        """List all registered environments with optional filtering.

        Args:
            env_type: Filter by environment type
            include_temporary: Whether to include temporary environments

        Returns:
            dict[str, EnvironmentEntry]: Filtered environment entries
        """
        envs = self.registry.environments.copy()

        if env_type:
            envs = {k: v for k, v in envs.items() if v.type == env_type}

        if not include_temporary:
            envs = {k: v for k, v in envs.items() if not v.is_temporary}

        return envs

    def find_by_name(self, name: str) -> Optional[tuple[str, EnvironmentEntry]]:
        """Find environment by name.

        Args:
            name: Environment name to search for

        Returns:
            Optional[tuple[str, EnvironmentEntry]]: (env_id, entry) tuple or None
        """
        for env_id, entry in self.registry.environments.items():
            if entry.name == name:
                return (env_id, entry)
        return None

    def find_by_env_id(self, env_id: str) -> Optional[tuple[str, EnvironmentEntry]]:
        """Find environment by env_id.

        Args:
            env_id: Environment ID to search for

        Returns:
            Optional[tuple[str, EnvironmentEntry]]: (env_id, entry) tuple or None
        """
        if env_id in self.registry.environments:
            return (env_id, self.registry.environments[env_id])
        return None

    def find_by_slug(self, slug: str) -> Optional[tuple[str, EnvironmentEntry]]:
        """Find first environment by slug (cloud identifier).

        Note: Same slug can be installed multiple times with different env_ids.
        Use find_all_by_slug() to get all installations.

        Args:
            slug: Environment slug to search for

        Returns:
            Optional[tuple[str, EnvironmentEntry]]: (env_id, entry) tuple or None
        """
        for env_id, entry in self.registry.environments.items():
            if entry.slug == slug:
                return (env_id, entry)
        return None

    def find_all_by_slug(self, slug: str) -> list[tuple[str, EnvironmentEntry]]:
        """Find ALL environments with given slug.

        Same slug can be installed multiple times (different locations, different env_ids).
        This method returns all installations.

        Args:
            slug: Environment slug to search for

        Returns:
            list[tuple[str, EnvironmentEntry]]: List of (env_id, entry) tuples
        """
        results = []
        for env_id, entry in self.registry.environments.items():
            if entry.slug == slug:
                results.append((env_id, entry))
        return results

    def find_by_path(self, path: Path) -> Optional[tuple[str, "EnvironmentEntry"]]:
        """Find environment by path.

        Args:
            path: Environment path to search for

        Returns:
            tuple[str, EnvironmentEntry] or None if not found
        """
        path = Path(path).resolve()
        for env_id, entry in self.registry.environments.items():
            if entry.path.resolve() == path:
                return (env_id, entry)
        return None

    def find_env_by_python_path(self, python_exe: Path) -> Optional[str]:
        """Find env_id for a registered environment containing the given Python executable.

        Matches by exact ``python_executable`` path or by checking if
        ``python_exe`` is within the environment's directory.

        Args:
            python_exe: Path to a Python executable.

        Returns:
            The env_id if found, ``None`` otherwise.
        """
        python_exe = Path(python_exe)
        for env_id, entry in self.list_environments().items():
            if entry.python_executable and Path(entry.python_executable) == python_exe:
                return env_id
            try:
                python_exe.relative_to(entry.path)
                return env_id
            except ValueError:
                continue
        return None

    def update_metadata(self, env_id: str, metadata: dict) -> None:
        """Update metadata for an environment.

        Args:
            env_id: Environment ID
            metadata: New metadata to merge with existing

        Raises:
            EnvironmentNotFoundError: If the environment is not found in the registry
        """
        with self._registry_lock():
            self.registry = self.load_registry()

            if env_id not in self.registry.environments:
                raise EnvironmentNotFoundError(f"Environment '{env_id}' not found in registry")

            self.registry.environments[env_id].metadata.update(metadata)
            self.save_registry()

        logger.debug("Updated metadata for environment: %s", env_id)

    def update_environment(self, env_id: str, **kwargs) -> None:
        """Update environment entry fields.

        Args:
            env_id: Environment ID
            **kwargs: Fields to update (name, description, tags, python_packages,
                      kernel_name, shell_prompt, icon, visibility, etc.)

        Raises:
            EnvironmentNotFoundError: If the environment is not found in the registry
            ValueError: If attempting to update protected fields (env_id, slug, path)

        Example:
            >>> registry.update_environment("abc1", name="New Name", tags=["quantum"])
            >>> registry.update_environment("abc1", python_packages={"numpy": "1.24.0"})
        """
        # Protected fields that cannot be updated
        protected_fields = {"env_id", "slug", "type"}

        for field in kwargs:
            if field in protected_fields:
                raise ValueError(f"Cannot update protected field: '{field}'")

        with self._registry_lock():
            self.registry = self.load_registry()

            if env_id not in self.registry.environments:
                raise EnvironmentNotFoundError(f"Environment '{env_id}' not found in registry")

            entry = self.registry.environments[env_id]
            for key, value in kwargs.items():
                if hasattr(entry, key):
                    setattr(entry, key, value)
                else:
                    logger.warning("Unknown field '%s' ignored for environment %s", key, env_id)

            self.save_registry()

        # Update per-env manifest
        self.save_env_manifest(env_id)

        logger.debug("Updated environment: %s with fields: %s", env_id, list(kwargs.keys()))

    def set_slug(self, env_id: str, slug: str) -> None:
        """Set slug for an environment after publishing.

        This method allows setting the slug once after an environment is published
        to the cloud. Once set, the slug cannot be changed.

        Args:
            env_id: Environment ID
            slug: Cloud slug to set (from API response after publish)

        Raises:
            EnvironmentNotFoundError: If the environment is not found in the registry
            ValueError: If slug is already set (cannot change existing slug)
            ValueError: If slug is invalid format
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid slug format: '{slug}'")

        with self._registry_lock():
            self.registry = self.load_registry()

            if env_id not in self.registry.environments:
                raise EnvironmentNotFoundError(f"Environment '{env_id}' not found in registry")

            entry = self.registry.environments[env_id]

            if entry.slug is not None:
                raise ValueError(
                    f"Slug already set for environment '{env_id}': '{entry.slug}'. "
                    "Cannot change existing slug."
                )

            entry.slug = slug
            self.save_registry()

        logger.info("Set slug for environment %s: %s", env_id, slug)

    # ── qbraid.yaml manifest ──────────────────────────────────────────────

    MANIFEST_FILENAME = "qbraid.yaml"

    # Fields to exclude from the manifest (local-only or path-dependent)
    _MANIFEST_EXCLUDE_FIELDS = {"path", "python_executable", "metadata"}

    def save_env_manifest(self, env_id: str) -> None:
        """Write current registry entry to <env_path>/qbraid.yaml.

        This creates a per-environment manifest that mirrors the registry entry,
        enabling recovery if the central registry is lost or corrupted.

        Args:
            env_id: Environment ID to save manifest for.
        """
        entry = self.registry.environments.get(env_id)
        if entry is None:
            logger.debug("Cannot save manifest: env_id '%s' not in registry", env_id)
            return

        if not entry.path.exists():
            logger.debug("Cannot save manifest: path does not exist: %s", entry.path)
            return

        manifest_path = entry.path / self.MANIFEST_FILENAME

        # Serialize entry, excluding local-only fields
        data = entry.model_dump(mode="json")
        for field in self._MANIFEST_EXCLUDE_FIELDS:
            data.pop(field, None)

        try:
            import yaml  # pylint: disable=import-outside-toplevel

            with open(manifest_path, "w", encoding="utf-8") as f:
                yaml.dump(data, f, default_flow_style=False, sort_keys=False, allow_unicode=True)
            logger.debug("Saved manifest for env_id '%s' at %s", env_id, manifest_path)
        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.warning("Failed to save manifest for env_id '%s': %s", env_id, err)

    def load_env_manifest(self, env_path: Path) -> Optional[dict[str, Any]]:
        """Read qbraid.yaml from an environment directory.

        Handles both new format (has env_id) and legacy format (name/icon only).
        Returns a dict of fields suitable for constructing an EnvironmentEntry,
        or None if no manifest exists or it can't be parsed.

        Args:
            env_path: Path to environment directory.

        Returns:
            Dict of manifest fields, or None.
        """
        manifest_path = env_path / self.MANIFEST_FILENAME
        if not manifest_path.exists():
            return None

        try:
            import yaml  # pylint: disable=import-outside-toplevel

            with open(manifest_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)

            if not isinstance(data, dict):
                return None

            # Detect legacy format (has 'icon' field, no 'env_id')
            if "env_id" not in data and "icon" in data:
                return self._migrate_legacy_manifest(data)

            return data

        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.warning("Failed to read manifest at %s: %s", manifest_path, err)
            return None

    @staticmethod
    def _migrate_legacy_manifest(data: dict[str, Any]) -> dict[str, Any]:
        """Convert legacy qbraid.yaml format to new manifest format.

        Legacy fields: name, description, kernel_name, shell_prompt,
        python_packages, python_version, tags, icon

        Args:
            data: Legacy manifest data.

        Returns:
            Dict with fields mapped to new format.
        """
        migrated: dict[str, Any] = {}

        # Direct mappings
        for field in (
            "name",
            "description",
            "kernel_name",
            "shell_prompt",
            "python_version",
            "tags",
        ):
            if data.get(field) is not None:
                migrated[field] = data[field]

        # icon → logo_url (legacy had a local path, not useful, but preserve if URL)
        icon = data.get("icon")
        if icon and isinstance(icon, str) and icon.startswith("http"):
            migrated["logo_url"] = {"light": icon, "dark": icon}

        # python_packages: legacy could be list or dict
        pkgs = data.get("python_packages")
        if isinstance(pkgs, list):
            migrated["python_packages"] = {p: "" for p in pkgs}
        elif isinstance(pkgs, dict):
            migrated["python_packages"] = pkgs

        return migrated

    @staticmethod
    def sanitize_manifest_for_upload(env_path: Path) -> None:
        """Sanitize qbraid.yaml for upload/publish by removing user-specific data.

        Strips: env_id, owner, installed_at, registered_at, is_temporary,
        last_updated, access_key, read_access_users.
        Keeps: name, description, tags, python_version, kernel_name,
        shell_prompt, python_packages, logo_url, visibility, slug, platform.

        Args:
            env_path: Path to the environment directory (the copy being archived).
        """
        manifest_path = env_path / "qbraid.yaml"
        if not manifest_path.exists():
            return

        try:
            import yaml  # pylint: disable=import-outside-toplevel

            with open(manifest_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)

            if not isinstance(data, dict):
                return

            # Remove user-specific fields
            for field in (
                "env_id",
                "owner",
                "installed_at",
                "registered_at",
                "is_temporary",
                "access_key",
                "read_access_users",
                "groups",
            ):
                data.pop(field, None)

            with open(manifest_path, "w", encoding="utf-8") as f:
                yaml.dump(data, f, default_flow_style=False, sort_keys=False, allow_unicode=True)

        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.warning("Failed to sanitize manifest at %s: %s", manifest_path, err)

    def sync_with_filesystem(self) -> dict[str, int]:
        """Sync registry with actual filesystem state.

        This will:
        1. Remove registry entries where paths no longer exist
        2. Auto-discover new qBraid environments in default paths
        3. Verify all registered environments still exist

        This operation is atomic - all changes are applied under a single lock
        to prevent race conditions with concurrent registry modifications.

        Returns:
            dict[str, int]: Statistics about sync operation
                - removed: Number of invalid entries removed
                - discovered: Number of new environments discovered
                - verified: Number of existing entries verified
        """
        stats = {"removed": 0, "discovered": 0, "verified": 0}

        # Phase 1: Discover environments on filesystem (no lock needed)
        # This is the slow part - reading filesystem, parsing configs, etc.
        discovered_envs: list[
            tuple[Path, Optional[str], Optional[str], Optional[dict[str, Any]], bool]
        ] = []
        env_paths = get_default_envs_paths()

        for env_path in env_paths:
            if not env_path.exists():
                continue

            try:
                for env_dir in env_path.iterdir():
                    if not env_dir.is_dir():
                        continue

                    # Skip directories that are currently being installed
                    install_marker = env_dir / ".qbraid_installing"
                    if install_marker.exists():
                        logger.debug(
                            "Skipping directory with installation in progress: %s", env_dir
                        )
                        continue

                    # Validate that this looks like a complete environment
                    python_candidates = [
                        env_dir / "pyenv" / "bin" / "python",
                        env_dir / "pyenv" / "bin" / "python3",
                        env_dir / "bin" / "python",
                        env_dir / "bin" / "python3",
                    ]
                    has_python = any(p.exists() for p in python_candidates)

                    if not has_python:
                        logger.debug(
                            "Skipping incomplete environment (no Python found): %s", env_dir
                        )
                        continue

                    # Read manifest for full metadata recovery
                    manifest = self.load_env_manifest(env_dir)

                    # Extract fields from manifest or fall back to detection
                    name = None
                    slug = None

                    if manifest:
                        name = manifest.get("name")
                        slug = manifest.get("slug")

                    # If directory name looks like a slug, extract slug
                    if slug is None and is_valid_slug(env_dir.name):
                        slug = env_dir.name

                    # Fall back to path extraction for name
                    if name is None:
                        name = extract_alias_from_path(env_dir)

                    is_temp = is_temporary_location(env_dir)

                    # Store discovered environment with manifest for later registration
                    discovered_envs.append((env_dir, name, slug, manifest, is_temp))

            except PermissionError as err:
                logger.warning("Permission denied accessing %s: %s", env_path, err)
                continue

        # Phase 2: Apply all changes atomically under a single lock
        with self._registry_lock():
            # Reload registry to get fresh state
            self.registry = self.load_registry()

            # Get current registered paths for deduplication
            registered_paths = {entry.path for entry in self.registry.environments.values()}

            # Remove entries where path no longer exists
            to_remove = []
            for env_id, entry in self.registry.environments.items():
                if not entry.path.exists():
                    to_remove.append(env_id)
                    logger.info(
                        "Removing registry entry with missing path: %s (env_id: %s)",
                        entry.name,
                        env_id,
                    )
                else:
                    stats["verified"] += 1

            for env_id in to_remove:
                del self.registry.environments[env_id]
                stats["removed"] += 1

            # Register discovered environments that aren't already registered
            for env_dir, name, slug, manifest, is_temp in discovered_envs:
                if env_dir in registered_paths:
                    continue  # Already registered

                try:
                    now = datetime.now(timezone.utc).isoformat()
                    env_type: EnvironmentType = "temporary" if is_temp else "qbraid-managed"

                    if manifest and manifest.get("env_id"):
                        # Full manifest available — restore entry with original env_id
                        env_id = manifest["env_id"]
                        # Avoid collision with existing env_id
                        if env_id in self.registry.environments:
                            env_id = self._generate_unique_env_id()

                        entry = EnvironmentEntry(
                            env_id=env_id,
                            slug=manifest.get("slug", slug),
                            owner=manifest.get("owner"),
                            path=env_dir,
                            type=manifest.get("type", env_type),
                            name=manifest.get("name", name) or env_dir.name,
                            description=manifest.get("description"),
                            tags=manifest.get("tags"),
                            logo_url=manifest.get("logo_url"),
                            python_version=manifest.get("python_version"),
                            platform=manifest.get("platform"),
                            kernel_name=manifest.get("kernel_name"),
                            shell_prompt=manifest.get("shell_prompt"),
                            python_packages=manifest.get("python_packages"),
                            visibility=manifest.get("visibility", "private"),
                            groups=manifest.get("groups"),
                            installed_at=manifest.get("installed_at", now),
                            is_temporary=is_temp,
                        )
                    elif manifest:
                        # Partial manifest (legacy or from published env) — use what we have
                        env_id = self._generate_unique_env_id()
                        entry = EnvironmentEntry(
                            env_id=env_id,
                            slug=manifest.get("slug", slug),
                            path=env_dir,
                            type=env_type,
                            name=manifest.get("name", name) or env_dir.name,
                            description=manifest.get("description"),
                            tags=manifest.get("tags"),
                            logo_url=manifest.get("logo_url"),
                            python_version=manifest.get("python_version"),
                            platform=manifest.get("platform"),
                            kernel_name=manifest.get("kernel_name"),
                            shell_prompt=manifest.get("shell_prompt"),
                            python_packages=manifest.get("python_packages"),
                            visibility=manifest.get("visibility", "private"),
                            installed_at=now,
                            is_temporary=is_temp,
                        )
                    else:
                        # No manifest — minimal entry (legacy behavior)
                        env_id = self._generate_unique_env_id()
                        entry = EnvironmentEntry(
                            env_id=env_id,
                            slug=slug,
                            path=env_dir,
                            type=env_type,
                            name=name or env_dir.name,
                            visibility="private",
                            installed_at=now,
                            is_temporary=is_temp,
                        )

                    self.registry.environments[env_id] = entry
                    registered_paths.add(env_dir)  # Update for dedup within this batch
                    stats["discovered"] += 1
                    logger.info("Auto-discovered environment: %s", env_dir.name)

                except (OSError, ValueError, RuntimeError) as err:
                    logger.warning("Skipping environment during auto-discovery: %s", err)
                    continue

            # Save all changes at once
            if stats["removed"] or stats["discovered"]:
                self.save_registry()

        logger.info("Registry sync complete: %s", stats)
        return stats

    def cleanup_temporary(self) -> list[str]:
        """Remove all temporary environments from registry and filesystem.

        Returns:
            list[str]: List of env_ids that were removed
        """
        removed = []

        for env_id, entry in list(self.registry.environments.items()):
            if not entry.is_temporary:
                continue

            # Remove from filesystem
            if entry.path.exists():
                try:
                    shutil.rmtree(entry.path)
                    logger.info("Removed temporary environment: %s", entry.path)
                except OSError as err:
                    logger.error("Failed to remove temporary environment %s: %s", env_id, err)
                    continue

            # Remove from registry
            self.unregister_environment(env_id)
            removed.append(env_id)

        return removed

    def export_to_file(self, output_path: Path) -> None:
        """Export registry to a JSON file.

        Args:
            output_path: Path to output file
        """
        registry_dict = self.registry.model_dump(mode="json")

        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(registry_dict, f, indent=2)

        logger.info("Registry exported to %s", output_path)

    def get_stats(self) -> dict[str, int]:
        """Get statistics about registered environments.

        Returns:
            dict[str, int]: Statistics including total count and counts by type
        """
        total = len(self.registry.environments)
        by_type: dict[str, int] = {}
        temporary_count = 0

        for entry in self.registry.environments.values():
            by_type[entry.type] = by_type.get(entry.type, 0) + 1
            if entry.is_temporary:
                temporary_count += 1

        return {
            "total": total,
            "qbraid_managed": by_type.get("qbraid-managed", 0),
            "external": by_type.get("external", 0),
            "temporary_total": by_type.get("temporary", 0),
            "temporary_marked": temporary_count,
        }
